1	/**
2	 * Family Category Visibility Test Suite
3	 *
4	 * Tests for #{#fcv1a} - Family Category Visibility
5	 * Specification: specs/specifications/family-category-visibility.md
6	 * Authority: system
7	 * Priority: Critical
8	 *
9	 * This test suite verifies that:
10	 * 1. Categories are family-scoped (not user-scoped)
11	 * 2. Category assignments are visible to all active family members
12	 * 3. Vendor rules are shared across family members
13	 * 4. Only active members can access family data
14	 */
15	
16	import { describe, it, expect, beforeEach, afterEach } from 'vitest';
17	import { createClient } from '@supabase/supabase-js';
18	
19	// Test configuration
20	const SUPABASE_URL = process.env.PUBLIC_SUPABASE_URL || '';
21	const SUPABASE_SERVICE_KEY = process.env.SUPABASE_SERVICE_ROLE_KEY || '';
22	
23	// Skip tests if Supabase is not configured
24	const describeIf = (condition: boolean) => (condition ? describe : describe.skip);
25	
26	describeIf(SUPABASE_URL && SUPABASE_SERVICE_KEY)(
27		'Family Category Visibility Integration Tests',
28		() => {
29			let supabase: ReturnType<typeof createClient>;
30	
31			// Test data IDs
32			let testFamilyId: string;
33			let testUser1Id: string;
34			let testUser2Id: string;
35			let testUser3Id: string; // Removed member
36			let testCategoryId: string;
37			let testReceiptId: string;
38	
39			beforeEach(async () => {
40				supabase = createClient(SUPABASE_URL, SUPABASE_SERVICE_KEY);
41	
42				// Create test family
43				const { data: family, error: familyError } = await supabase
44					.from('families')
45					.insert({ name: 'Test Family for Category Visibility' })
46					.select()
47					.single();
48	
49				if (familyError) throw familyError;
50				testFamilyId = family.id;
51	
52				// Create test users
53				const { data: user1, error: user1Error } = await supabase.auth.admin.createUser({
54					email: `test-user1-${Date.now()}@example.com`,
55					password: 'testpassword123',
56					email_confirm: true
57				});
58				if (user1Error) throw user1Error;
59				testUser1Id = user1.user.id;
60	
61				const { data: user2, error: user2Error } = await supabase.auth.admin.createUser({
62					email: `test-user2-${Date.now()}@example.com`,
63					password: 'testpassword123',
64					email_confirm: true
65				});
66				if (user2Error) throw user2Error;
67				testUser2Id = user2.user.id;
68	
69				const { data: user3, error: user3Error } = await supabase.auth.admin.createUser({
70					email: `test-user3-${Date.now()}@example.com`,
71					password: 'testpassword123',
72					email_confirm: true
73				});
74				if (user3Error) throw user3Error;
75				testUser3Id = user3.user.id;
76	
77				// Add users to family
78				await supabase.from('family_members').insert([
79					{
80						family_id: testFamilyId,
81						user_id: testUser1Id,
82						status: 'active',
83						role: 'owner',
84						is_default: true
85					},
86					{
87						family_id: testFamilyId,
88						user_id: testUser2Id,
89						status: 'active',
90						role: 'member',
91						is_default: true
92					},
93					{
94						family_id: testFamilyId,
95						user_id: testUser3Id,
96						status: 'removed',
97						role: 'member',
98						is_default: false
99					}
100				]);
101			});
102	
103			afterEach(async () => {
104				// Cleanup test data
105				if (testCategoryId) {
106					await supabase.from('categories').delete().eq('id', testCategoryId);
107				}
108				if (testReceiptId) {
109					await supabase.from('receipts').delete().eq('id', testReceiptId);
110				}
111				if (testFamilyId) {
112					await supabase.from('family_members').delete().eq('family_id', testFamilyId);
113					await supabase.from('families').delete().eq('id', testFamilyId);
114				}
115				if (testUser1Id) {
116					await supabase.auth.admin.deleteUser(testUser1Id);
117				}
118				if (testUser2Id) {
119					await supabase.auth.admin.deleteUser(testUser2Id);
120				}
121				if (testUser3Id) {
122					await supabase.auth.admin.deleteUser(testUser3Id);
123				}
124			});
125	
126			describe('#{#fcv1b} - Family Category Visibility', () => {
127				it('should allow all active family members to see categories created by any member', async () => {
128					// User 1 creates a category
129					const { data: user1Session } = await supabase.auth.signInWithPassword({
130						email: `test-user1-${Date.now()}@example.com`,
131						password: 'testpassword123'
132					});
133	
134					const user1Client = createClient(SUPABASE_URL, SUPABASE_SERVICE_KEY, {
135						auth: { persistSession: false }
136					});
137					await user1Client.auth.setSession({
138						access_token: user1Session.session!.access_token,
139						refresh_token: user1Session.session!.refresh_token
140					});
141	
142					const { data: category, error: createError } = await user1Client
143						.from('categories')
144						.insert({ family_id: testFamilyId, name: 'Test Groceries', color: '#10B981' })
145						.select()
146						.single();
147	
148					expect(createError).toBeNull();
149					expect(category).toBeDefined();
150					testCategoryId = category!.id;
151	
152					// User 2 should be able to see the category
153					const { data: user2Session } = await supabase.auth.signInWithPassword({
154						email: `test-user2-${Date.now()}@example.com`,
155						password: 'testpassword123'
156					});
157	
158					const user2Client = createClient(SUPABASE_URL, SUPABASE_SERVICE_KEY, {
159						auth: { persistSession: false }
160					});
161					await user2Client.auth.setSession({
162						access_token: user2Session.session!.access_token,
163						refresh_token: user2Session.session!.refresh_token
164					});
165	
166					const { data: categories, error: fetchError } = await user2Client
167						.from('categories')
168						.select('*')
169						.eq('family_id', testFamilyId);
170	
171					expect(fetchError).toBeNull();
172					expect(categories).toHaveLength(1);
173					expect(categories![0].name).toBe('Test Groceries');
174				});
175	
176				it('should prevent removed family members from seeing categories', async () => {
177					// Create category as admin
178					const { data: category, error: createError } = await supabase
179						.from('categories')
180						.insert({ family_id: testFamilyId, name: 'Test Category', color: '#10B981' })
181						.select()
182						.single();
183	
184					expect(createError).toBeNull();
185					testCategoryId = category!.id;
186	
187					// User 3 (removed) should NOT be able to see the category
188					const { data: user3Session } = await supabase.auth.signInWithPassword({
189						email: `test-user3-${Date.now()}@example.com`,
190						password: 'testpassword123'
191					});
192	
193					const user3Client = createClient(SUPABASE_URL, SUPABASE_SERVICE_KEY, {
194						auth: { persistSession: false }
195					});
196					await user3Client.auth.setSession({
197						access_token: user3Session.session!.access_token,
198						refresh_token: user3Session.session!.refresh_token
199					});
200	
201					const { data: categories, error: fetchError } = await user3Client
202						.from('categories')
203						.select('*')
204						.eq('family_id', testFamilyId);
205	
206					// Should return empty array due to RLS
207					expect(fetchError).toBeNull();
208					expect(categories).toHaveLength(0);
209				});
210	
211				it('should enforce unique category names per family', async () => {
212					// User 1 creates a category
213					const { data: category1, error: error1 } = await supabase
214						.from('categories')
215						.insert({ family_id: testFamilyId, name: 'Groceries', color: '#10B981' })
216						.select()
217						.single();
218	
219					expect(error1).toBeNull();
220					testCategoryId = category1!.id;
221	
222					// User 2 tries to create same category (should fail)
223					const { error: error2 } = await supabase
224						.from('categories')
225						.insert({ family_id: testFamilyId, name: 'groceries', color: '#FF0000' });
226	
227					expect(error2).toBeDefined();
228					expect(error2?.code).toBe('23505'); // Unique constraint violation
229				});
230			});
231	
232			describe('#{#fcv2a} - Active Member Filter', () => {
233				it('should only allow active members to view transactions', async () => {
234					// Create transaction as admin
235					const { data: transaction, error: createError } = await supabase
236						.from('transactions')
237						.insert({
238							family_id: testFamilyId,
239							transaction_date: '2026-01-01',
240							vendor_name: 'Test Vendor',
