275	
276					const user3Client = createClient(SUPABASE_URL, SUPABASE_SERVICE_KEY, {
277						auth: { persistSession: false }
278					});
279					await user3Client.auth.setSession({
280						access_token: user3Session.session!.access_token,
281						refresh_token: user3Session.session!.refresh_token
282					});
283	
284					const { data: transactions3 } = await user3Client
285						.from('transactions')
286						.select('*')
287						.eq('family_id', testFamilyId);
288	
289					expect(transactions3).toHaveLength(0);
290	
291					// Cleanup
292					await supabase.from('transactions').delete().eq('id', transaction!.id);
293				});
294			});
295	
296			describe('#{#fcv3a} - Vendor Rule Sharing', () => {
297				it('should allow vendor rules to apply across all family members', async () => {
298					// User 1 creates a vendor rule
299					const { data: category } = await supabase
300						.from('categories')
301						.insert({ family_id: testFamilyId, name: 'Groceries', color: '#10B981' })
302						.select()
303						.single();
304	
305					testCategoryId = category!.id;
306	
307					const { data: rule, error: ruleError } = await supabase
308						.from('vendor_category_rules')
309						.insert({
310							family_id: testFamilyId,
311							vendor_pattern: 'costco',
312							category_id: testCategoryId
313						})
314						.select()
315						.single();
316	
317					expect(ruleError).toBeNull();
318					expect(rule).toBeDefined();
319	
320					// User 2 should be able to see the rule
321					const { data: user2Session } = await supabase.auth.signInWithPassword({
322						email: `test-user2-${Date.now()}@example.com`,
323						password: 'testpassword123'
324					});
325	
326					const user2Client = createClient(SUPABASE_URL, SUPABASE_SERVICE_KEY, {
327						auth: { persistSession: false }
328					});
329					await user2Client.auth.setSession({
330						access_token: user2Session.session!.access_token,
331						refresh_token: user2Session.session!.refresh_token
332					});
333	
334					const { data: rules, error: fetchError } = await user2Client
335						.from('vendor_category_rules')
336						.select('*')
337						.eq('family_id', testFamilyId);
338	
339					expect(fetchError).toBeNull();
340					expect(rules).toHaveLength(1);
341					expect(rules![0].vendor_pattern).toBe('costco');
342	
343					// Cleanup
344					await supabase.from('vendor_category_rules').delete().eq('id', rule!.id);
345				});
346	
347				it('should enforce unique vendor patterns per family', async () => {
348					const { data: category } = await supabase
349						.from('categories')
350						.insert({ family_id: testFamilyId, name: 'Groceries', color: '#10B981' })
