378	
379					// Cleanup
380					await supabase.from('vendor_category_rules').delete().eq('id', rule1!.id);
381				});
382			});
383	
384			describe('#{#fcv4a} - Category Name Uniqueness', () => {
385				it('should enforce case-insensitive unique category names per family', async () => {
